def two_sum(nums: list[int], target: int) -> tuple[int, int]:
    """
    Finds two indices i and j such that nums[i] + nums[j] == target, with i < j.
    Exactly one such pair is guaranteed to exist.
    """
    num_map = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_map:
            j = num_map[complement]
            # Since we iterate in increasing order of index, the stored index j will be less than i.
            # We need to return (i, j) such that i < j.
            # If we found the complement, the indices are j (from map) and i (current).
            # We must ensure the returned tuple (i', j') has i' < j'.
            return (j, i) if j < i else (i, j)
        num_map[num] = i
    # This line should theoretically never be reached based on the problem description
    return (-1, -1)
