def evaluate(expr: str) -> int:
    """
    Evaluates an arithmetic expression containing non-negative integers, +, -, *, / and parentheses,
    with normal operator precedence. Spaces may appear anywhere. Division is integer division
    that truncates toward zero.
    """
    def apply_op(op, b, a):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            # Integer division truncating toward zero
            if b == 0:
                raise ZeroDivisionError("Division by zero")
            return int(a / b)
        return 0

    def precedence(op):
        if op == '+' or op == '-':
            return 1
        if op == '*' or op == '/':
            return 2
        return 0

    def process_expression(tokens):
        values = []
        ops = []

        def process_op_on_stack():
            op = ops.pop()
            right = values.pop()
            left = values.pop()
            values.append(apply_op(op, right, left))

        for token in tokens:
            if isinstance(token, int):
                values.append(token)
            elif token == '(':
                ops.append(token)
            elif token == ')':
                while ops[-1] != '(':
                    process_op_on_stack()
                ops.pop()  # Pop '('
            else:  # Operator
                while (ops and ops[-1] != '(' and
                       precedence(ops[-1]) >= precedence(token)):
                    process_op_on_stack()
                ops.append(token)

        while ops:
            process_op_on_stack()
        return values[0]

    # Tokenization
    tokens = []
    i = 0
    while i < len(expr):
        char = expr[i]
        if char.isspace():
            i += 1
            continue
        elif char.isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        elif char in '+-*/()':
            tokens.append(char)
            i += 1
        else:
            # Should not happen based on problem description
            raise ValueError(f"Invalid character in expression: {char}")

    return process_expression(tokens)
