def caesar(s: str, k: int) -> str:
    result = []
    for char in s:
        if char.isalpha():
            # Determine the base ASCII value for the case
            base = ord('A') if char.isupper() else ord('a')
            # Shift the character, wrapping around using modulo 26
            shifted = (ord(char) - base + k) % 26
            result.append(chr(shifted + base))
        else:
            result.append(char)
    return ''.join(result)
